    for base in (xdg, Path(env.get('HOME', str(Path.home())))):
        for name in ('taskrc.yml', 'taskrc.yaml', '.taskrc.yml', '.taskrc.yaml'):
            result.update(_read_config(base / name))
    for directory in reversed((cwd, *cwd.parents)):
        for name in ('.taskrc.yml', '.taskrc.yaml'):
            result.update(_read_config(directory / name))
    for key, envkey in BOOLS.items():
        if envkey in env:
            val = env[envkey].lower()
            result[key] = val in ('true', '1', 'yes', 'on')
    if 'TASK_CONCURRENCY' in env:
        try: result['concurrency'] = int(env['TASK_CONCURRENCY'])
        except ValueError: pass
