    return cmds


def _summary_value(value):
    if value is None:
        return ""
    if isinstance(value, bool):
        return str(value).lower()
    if isinstance(value, (list, tuple)):
        return "[" + " ".join(map(str, value)) + "]"
    if isinstance(value, dict):
        if len(value) == 1 and next(iter(value)) in ("sh", "ref"):
            key = next(iter(value))
            return f"{key}: {value[key]}"
        return "map[" + " ".join(f"{k}:{v}" for k, v in value.items()) + "]"
    return str(value)


def _lookup_task(config, name):
    tasks = config.get("tasks") or {}
    if name in tasks:
        return name, tasks[name]
    for canonical, task in tasks.items():
        if not isinstance(task, dict):
            continue
        aliases = task.get("aliases", []) or []
        if isinstance(aliases, str):
            aliases = [aliases]
        if name in aliases:
            return canonical, task
    return name, None


